/**
 * Implementation of the GLTF 2.0 format exporter.
 *
 * @category Exporter
 */
export class GltfExporter extends CoreExporter {
    static writeBufferView(resources: any, json: any, buffer: any): void;
    static createPrimitive(resources: any, json: any, mesh: any, options?: {}): {
        attributes: {};
    };
    /** @ignore */
    collectResources(root: any): {
        buffers: any[];
        cameras: any[];
        entities: any[];
        materials: any[];
        skins: any[];
        textures: any[];
        entityMeshInstances: any[];
        bufferViewMap: Map<any, any>;
        compressibleTexture: Set<any>;
        channelCopies: Map<any, any>;
    };
    writeBufferViews(resources: any, json: any): void;
    writeCameras(resources: any, json: any): void;
    /**
     * Returns the texture a map of a material is exported with: the texture itself, or a copy of
     * it with the channel the material reads moved into the channel glTF reads.
     *
     * @param {object} resources - The resources of the export.
     * @param {StandardMaterial} material - The material.
     * @param {string} semantic - The map, for example 'diffuseTransmissionMap'.
     * @returns {Texture|ChannelCopy|null} The texture to export.
     * @private
     */
    private getExportedTexture;
    attachTexture(resources: any, material: any, destination: any, name: any, textureSemantic: any, json: any): void;
    attachRoughnessTexture(resources: any, material: any, destination: any, name: any, gloss: any, json: any): void;
    addExtension(json: any, output: any, name: any, data?: {}): void;
    writeStandardMaterial(resources: any, mat: any, output: any, json: any): void;
    writeMaterials(resources: any, json: any): void;
    writeNodes(resources: any, json: any): void;
    writeMeshes(resources: any, json: any, options: any): void;
    writeSkins(resources: any, json: any): void;
    convertTextures(srcTextures: any, options: any): any[];
    /**
     * Converts a copy of a texture to a canvas, with a channel copied into another. The texture is
     * rendered to a linear RGBA8 target, so the channel holds the value the material samples,
     * decoded from sRGB. The channel is copied before the pixels reach a canvas, which stores them
     * premultiplied by alpha and so loses the color of texels with zero alpha.
     *
     * @param {ChannelCopy} copy - The copy of the texture.
     * @param {object} options - The texture options.
     * @param {number} [options.maxTextureSize] - The maximum size of the texture.
     * @returns {Promise<HTMLCanvasElement|undefined>} The canvas.
     * @private
     */
    private channelCopyToCanvas;
    writeTextures(resources: any, textureCanvases: any, json: any, options: any): Promise<any[]>;
    getBlob(canvas: any, mimeType: any): any;
    getPaddedArrayBuffer(arrayBuffer: any, paddingByte?: number): any;
    buildJson(resources: any, options: any): Promise<{
        asset: {
            version: string;
            generator: string;
        };
        scenes: {
            nodes: number[];
        }[];
        images: any[];
        samplers: any[];
        textures: any[];
        scene: number;
    }>;
    /**
     * Converts a hierarchy of entities to GLB format. Clearcoat and sheen gloss maps are exported
     * unchanged as roughness textures, which is only correct for materials that enable
     * {@link StandardMaterial#clearCoatGlossInvert} or {@link StandardMaterial#sheenGlossInvert},
     * such as materials imported from glTF.
     *
     * @param {Entity} entity - The root of the entity hierarchy to convert.
     * @param {object} options - Object for passing optional arguments.
     * @param {number} [options.maxTextureSize] - Maximum texture size. Texture is resized if over the size.
     * @param {boolean} [options.stripUnusedAttributes] - If true, removes unused vertex attributes:
     *
     * - Texture coordinates not referenced by materials
     * - Vertex colors if not used by materials
     * - Tangents if no normal maps are used
     * - Skinning data if no skinned meshes exist
     *
     * Defaults to false.
     * @returns {Promise<ArrayBuffer>} - The GLB file content.
     */
    build(entity: Entity, options?: {
        maxTextureSize?: number;
        stripUnusedAttributes?: boolean;
    }): Promise<ArrayBuffer>;
}
import { CoreExporter } from './core-exporter.js';
import type { Entity } from '../../framework/entity.js';
